const order = $('On Shopify Order Created').first().json || {};
const cfg = $('Store Configuration').first().json || {};
const rawPhone = String(
  order.shipping_address?.phone || order.phone || order.customer?.phone || order.billing_address?.phone || ''
).trim();
const cleanPhone = rawPhone.replace(/\D/g, '');
if (cleanPhone.length < 8) return [];
const totalAmount = Number(order.total_price || 0);
const currency = String(order.currency || 'USD').toUpperCase();
const itemsSummary = (order.line_items || []).slice(0, 4).map((li) => `${li.quantity}x ${li.title}`).join(', ');
return [{
  json: {
    orderId: String(order.id || ''),
    orderNumber: String(order.name || ('#' + (order.order_number || order.id || ''))),
    customerName: String(order.shipping_address?.first_name || order.customer?.first_name || 'there').trim(),
    email: String(order.email || order.customer?.email || '').trim(),
    cleanPhone,
    totalFormatted: `${totalAmount.toFixed(2)} ${currency}`,
    totalAmount,
    itemsSummary: itemsSummary || 'Your items',
    orderStatusUrl: String(order.order_status_url || ''),
    isVipOrder: totalAmount >= Number(cfg.vipOrderThreshold || 250),
    storeName: cfg.storeName,
    spreadsheetId: cfg.spreadsheetId,
    slackOpsChannelId: cfg.slackOpsChannelId,
  },
}];

const order = $('On Shopify Order Fulfilled').first().json || {};
const cfg = $('Fulfillment Configuration').first().json || {};
const rawPhone = String(
  order.shipping_address?.phone || order.phone || order.customer?.phone || order.billing_address?.phone || ''
).trim();
const cleanPhone = rawPhone.replace(/\D/g, '');
if (cleanPhone.length < 8) return [];
const latestFulfillment = Array.isArray(order.fulfillments) && order.fulfillments.length ? order.fulfillments[order.fulfillments.length - 1] : {};
const trackingCompany = String(latestFulfillment.tracking_company || 'Carrier');
const trackingNumber = String(latestFulfillment.tracking_number || 'Pending');
const trackingUrl = String(latestFulfillment.tracking_url || order.order_status_url || '');
const delayHours = Number(cfg.deliveryPollDelayHours || 72);
const deliveryPollDueAt = new Date(Date.now() + delayHours * 3600 * 1000).toISOString();
return [{
  json: {
    orderId: String(order.id || ''),
    orderNumber: String(order.name || ('#' + (order.order_number || order.id || ''))),
    customerName: String(order.shipping_address?.first_name || order.customer?.first_name || 'there').trim(),
    cleanPhone,
    trackingCompany,
    trackingNumber,
    trackingUrl,
    deliveryPollDueAt,
    storeName: cfg.storeName,
    spreadsheetId: cfg.spreadsheetId,
  },
}];

const order = $('On Shopify Order Cancelled').first().json || {};
const cfg = $('Cancellation Configuration').first().json || {};
const rawPhone = String(
  order.shipping_address?.phone || order.phone || order.customer?.phone || order.billing_address?.phone || ''
).trim();
const cleanPhone = rawPhone.replace(/\D/g, '');
if (cleanPhone.length < 8) return [];
return [{
  json: {
    orderId: String(order.id || ''),
    orderNumber: String(order.name || ('#' + (order.order_number || order.id || ''))),
    customerName: String(order.shipping_address?.first_name || order.customer?.first_name || 'there').trim(),
    cleanPhone,
    cancelReason: String(order.cancel_reason || 'customer request'),
    storeName: cfg.storeName,
    spreadsheetId: cfg.spreadsheetId,
  },
}];

const cfg = $('Poll Sweep Configuration').first().json || {};
const now = Date.now();
const due = [];
for (const item of $input.all()) {
  const row = item.json;
  if (!row || !row.orderId || !row.phone) continue;
  if (row.status !== 'Shipped' || row.pollSent === 'Yes') continue;
  const dueMs = Date.parse(String(row.deliveryPollDueAt || ''));
  if (!Number.isFinite(dueMs) || dueMs > now) continue;
  due.push({ json: { ...row, storeName: cfg.storeName, spreadsheetId: cfg.spreadsheetId } });
}
return due;

const row = $input.first()?.json;
if (!row || !row.orderId || row.status !== 'Shipped') return [];
const ev = $('When Customer Votes on Delivery Poll').first().json || {};
const cfg = $('Vote Handler Configuration').first().json || {};
const selected = ev.vote?.selectedOptionIndices;
if (!Array.isArray(selected) || selected.length === 0) return [];
const idx = Number(selected[0]);
if (idx < 0 || idx > 2) return [];
const outcomes = ['loved_it', 'delivery_issue', 'still_waiting'];
return [{
  json: {
    ...row,
    chatId: String(ev.chat?.id || row.phone),
    outcome: outcomes[idx],
    storeName: cfg.storeName,
    spreadsheetId: cfg.spreadsheetId,
    slackOpsChannelId: cfg.slackOpsChannelId,
    reviewUrl: cfg.reviewUrl,
  },
}];
